"""Read and write data/seedpoet.json, the word data shared by the Go and JavaScript libraries.

The layout is fixed (one list per line) so that regenerating it gives a stable, reviewable diff.
"""
import json
import os

PATH = os.path.join(os.path.dirname(__file__), "..", "data", "seedpoet.json")
COMMENT = ("Generated by scripts/categorize.py and scripts/phonetic_rhymes.py from data/english.txt. "
           "Single source for the Go and JavaScript libraries. Do not edit by hand.")


def load():
    if os.path.exists(PATH):
        with open(PATH) as f:
            return json.load(f)
    return {"format": 1, "verbs": [], "adjectives": [], "nouns": [], "rhymes": []}


def save(data):
    out = '{\n  "format": 1,\n  "comment": ' + json.dumps(COMMENT) + ',\n'
    for key in ("verbs", "adjectives", "nouns"):
        out += '  "' + key + '": ' + json.dumps(data[key]) + ',\n'
    out += '  "rhymes": [\n'
    out += ',\n'.join('    [' + json.dumps(k) + ', ' + json.dumps(v) + ']' for k, v in data["rhymes"])
    out += '\n  ]\n}\n'
    json.loads(out)
    with open(PATH, "w") as f:
        f.write(out)
